function daDance(string $value):string{return in_array($value,['bachata','salsa'],true)?$value:'bachata';}
function daRound(PDO $pdo,int $id):array{$s=$pdo->prepare('SELECT * FROM bdc_scoring_rounds WHERE id=:id LIMIT 1');$s->execute(['id'=>$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('Scoring round not found.');return $r;}
